[FormControlAttribute('TFMMenuMakerCtrl','/Resources/html/TFMMenuMakerCtrl',classstr(TFMMenuMakerCtrlBuild))]
class TFMMenuMakerCtrl extends FormTemplateContainerControl
{
    TFMMenuConfigurator configurator;
    FormProperty        SendAvailableMenuItemsToJavascriptProperty;
    FormProperty        SendSelectedMenuItemsToJavascriptProperty;
    FormProperty        SendSaveRequestToControlToJavascriptProperty;
    FormProperty        SendUpdatingToJavascriptProperty;
    Map                 createdMenuItems;
    int                 counter = 0;


}

Method.Source:
protected void new(FormBuildControl _build, FormRun _formRun)
{
    super(_build, _formRun);
    this.setTemplateId('TFMMenuMakerCtrl');
    this.setResourceBundleName('/Resources/html/TFMMenuMakerCtrl');

    SendAvailableMenuItemsToJavascriptProperty = this.addProperty(methodstr(TFMMenuMakerCtrl, SendAvailableMenuItemsToJavascript), Types::String);
    SendSelectedMenuItemsToJavascriptProperty = this.addProperty(methodstr(TFMMenuMakerCtrl, SendSelectedMenuItemsToJavascript), Types::String);
    SendSaveRequestToControlToJavascriptProperty = this.addProperty(methodstr(TFMMenuMakerCtrl, SendSaveRequestToControlToJavascript), Types::String);
    SendUpdatingToJavascriptProperty = this.addProperty(methodstr(TFMMenuMakerCtrl, SendUpdatingToJavascript), Types::String);

    this.createdMenuItems = new Map(Types::String, Types::Class);
}

public void sendMenuItemsToControl(List selectedMenuItems, Map availableMenuItems)
{
    this.SendSelectedMenuItemsToJavascript(FormJsonSerializer::serializeClass(this.getMenuItemsSetupForGroupList(selectedMenuItems)));
    this.SendAvailableMenuItemsToJavascript(FormJsonSerializer::serializeClass(this.getAvailableMenuItemsList(availableMenuItems)));
}

[FormCommandAttribute('setMenuItemsSetup')]
public void setMenuItemsSetup(str _json)
{
    info('Setup saved');
    List newMenuSetup = FormJsonSerializer::deserializeCollection(classNum(List), _json, Types::String);
    configurator.savePermissionsForGroupAndUserGroup(newMenuSetup);
}

[FormCommandAttribute('getTranslation')]
public str getLocalization(str _localizationKey)
{
    str sReturn;
    TFMLocalizationContract contract = new TFMLocalizationContract();

    str labelStr = SysLabel::labelId2String('@TFM:' + _localizationKey);
    contract.parmKey(_localizationKey);
    contract.parmTranslation(labelStr);
    sReturn = FormJsonSerializer::serializeClass(contract);
    return sReturn;
}

public List getAvailableMenuItemsList(Map _availableMenuItems)
{
    TFMPage page;
    TFMMenuConfigContract contract;
    boolean first = true;
    List availableMenuItems = new List(Types::Class);
    MapEnumerator availableMenuItemsEnum = _availableMenuItems.getEnumerator();
    Map sortedAvailableMenuItems = new Map(Types::Integer, Types::Class);
    MapEnumerator sortedAvailableMenuItemsEnum;

    while(availableMenuItemsEnum.moveNext())
    {
        contract = this.convertFromPageToContract(availableMenuItemsEnum.currentValue());
        if(first)
        {
            contract.parmUpdated(timeNow());
            first = false;
        }

        // make sure that Receive, Pick and Count are put in the start of the main menu.
        if(availableMenuItemsEnum.currentKey() == TFMConstants::Receive())
        {
            sortedAvailableMenuItems.add(6, contract);
        }
        else if(availableMenuItemsEnum.currentKey() == TFMConstants::Pick())
        {
            sortedAvailableMenuItems.add(4, contract);
        }
        else if(availableMenuItemsEnum.currentKey() == TFMConstants::Count())
        {
            sortedAvailableMenuItems.add(2, contract);
        }
        else
        {
            availableMenuItems.addEnd(contract);
        }
    }

    sortedAvailableMenuItemsEnum = sortedAvailableMenuItems.getEnumerator();
    while(sortedAvailableMenuItemsEnum.moveNext())
    {
        availableMenuItems.addStart(sortedAvailableMenuItemsEnum.currentValue());
    }

    return  availableMenuItems;
}

public List getMenuItemsSetupForGroupList(List _menuItems)
{
    TFMMenuConfigContract contract;
    List menuItems = new List(Types::Class);
    ListEnumerator menuItemsEnum = _menuItems.getEnumerator();
    boolean first = true;

    while(menuItemsEnum.moveNext())
    {
        contract = this.convertFromPageToContract(menuItemsEnum.current());
        if(first)
        {
            contract.parmUpdated(timeNow());
            first = false;
        }
        menuItems.addEnd(contract);
    }
    return menuItems;
}

private TFMMenuConfigContract convertFromPageToContract(TFMPage _page)
{
    TFMMenuConfigContract contract;
    if(createdMenuItems.exists(_page.parmId()))
    {
        contract = createdMenuItems.lookup(_page.parmId());
    }
    else
    {
        contract = new TFMMenuConfigContract();
        contract.parmPageId(_page.parmId());
        //contract.parmTitle(_page.parmTitle());
        contract.parmTitle(TFMListVisualization::getMenuTitle(_page.parmTitle()));
        //contract.parmIconName('https://cdn-icons-png.flaticon.com/128/9393/9393642.png'); //Used for testing
        contract.parmIconName(TFMDocGetMedia::getURLFromIconName(_page.parmIcon()));
    }

    contract.parmIsStandard(configurator.isStandard(_page));
    return contract;
}
